(()=>{
 const root=document.querySelector('#lead-app');if(!root)return;
 const copy={bm:{eyebrow:'TEMUI KEDIAMAN ANDA',title:'Langkah pertama bermula di sini.',intro:'Kongsikan pilihan anda untuk membantu kami memahami keperluan anda.',step:'Langkah',of:'daripada',next:'Seterusnya',back:'Kembali',submit:'Hantar',sending:'Menghantar…',optional:'Pilihan',questions:['Siapakah nama anda?','Berapakah julat gaji bulanan anda?','Apakah pekerjaan anda?','Hartanah manakah yang anda minati?','Berapakah bajet pembelian anda?','Bagaimana kami boleh menghubungi anda?'],hints:['Mari berkenalan.','Pilih satu julat dalam Ringgit Malaysia.','Nyatakan pekerjaan atau bidang anda.','Pilih satu jenis hartanah.','Anggaran harga hartanah, bukan bayaran bulanan.','Masukkan nombor telefon yang boleh dihubungi.'],placeholders:['Nama penuh anda','','Contoh: Jurutera, usahawan atau pesara','','','Contoh: 012 345 6789'],salary:['Bawah RM3,000','RM3,000–RM5,000','RM5,000–RM8,000','RM8,000–RM12,000','Lebih RM12,000'],types:['Kondominium','Rumah bertanah','Komersial'],budget:['Bawah RM300,000','RM300,000–RM500,000','RM500,000–RM800,000','RM800,000–RM1 juta','Lebih RM1 juta'],whatsapp:'Anda boleh menghubungi saya melalui WhatsApp.',privacy:'Dengan menghantar, anda membenarkan wakil pertanyaan laman ini menggunakan maklumat ini untuk menghubungi anda tentang minat hartanah anda.',required:'Sila lengkapkan jawapan ini sebelum meneruskan.',phoneError:'Masukkan nombor telefon yang sah (9–15 digit).',textError:'Masukkan sekurang-kurangnya 2 aksara.',error:'Maklumat belum dihantar. Sila cuba lagi; jawapan anda masih tersedia.',thanks:'Terima kasih!',received:'Pertanyaan anda telah diterima.',followup:'Wakil pertanyaan kami boleh menghubungi anda berdasarkan maklumat yang diberikan.',done:'Kembali menerokai Ophira',tick:'Pertanyaan berjaya dihantar',phone:'Nombor telefon'},en:{eyebrow:'FIND YOUR NEXT HOME',title:'Your next chapter starts here.',intro:'Share a few details to help us understand what you’re looking for.',step:'Step',of:'of',next:'Next',back:'Back',submit:'Submit',sending:'Submitting…',questions:['What’s your name?','What’s your monthly salary range?','What do you do for work?','What property type interests you?','What’s your purchase budget?','How can we reach you?'],hints:['Let’s get acquainted.','Choose one range in Malaysian Ringgit.','Tell us your occupation or line of work.','Choose one property type.','Your estimated property price, not a monthly payment.','Enter a phone number where we can reach you.'],placeholders:['Your full name','','E.g. Engineer, business owner or retiree','','','E.g. 012 345 6789'],salary:['Below RM3,000','RM3,000–RM5,000','RM5,000–RM8,000','RM8,000–RM12,000','Above RM12,000'],types:['Condo','Landed','Commercial'],budget:['Below RM300,000','RM300,000–RM500,000','RM500,000–RM800,000','RM800,000–RM1 million','Above RM1 million'],whatsapp:'You may contact me on WhatsApp.',privacy:'By submitting, you allow this site’s enquiry representative to use these details to contact you about your property interest.',required:'Please answer this question before continuing.',phoneError:'Enter a valid phone number (9–15 digits).',textError:'Please enter at least 2 characters.',error:'Your details haven’t been sent. Please try again; your answers are still here.',thanks:'Thank you!',received:'Your enquiry has been received.',followup:'Our enquiry representative can follow up using the details you provided.',done:'Continue exploring Ophira',tick:'Enquiry submitted successfully',phone:'Phone number'}};
 const fields=['name','salary','occupation','propertyType','budget','phone'];
 const choices={salary:['below-3000','3000-5000','5000-8000','8000-12000','above-12000'],propertyType:['condo','landed','commercial'],budget:['below-300000','300000-500000','500000-800000','800000-1000000','above-1000000']};
 const values={name:'',salary:'',occupation:'',propertyType:'',budget:'',phone:'',whatsapp:false};
 let step=0,busy=false,complete=false,error='',direction=1,id=crypto.randomUUID();
 const t=()=>copy[typeof language!=='undefined'&&language==='en'?'en':'bm'];
 const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function render(focus=false){const c=t();document.querySelector('#lead-capture').setAttribute('aria-label',language==='en'?'Property enquiry form':'Borang pertanyaan hartanah');
  if(complete){root.innerHTML=`<div class="lead-success" role="status"><span class="success-symbol" aria-hidden="true">✓</span><p class="lead-eyebrow">${c.tick}</p><h2 tabindex="-1">${c.thanks}</h2><p><strong>${c.received}</strong></p><p>${c.followup}</p><a href="#residences" class="lead-primary">${c.done}</a></div>`;if(focus)root.querySelector('h2').focus({preventScroll:true});return}
  const field=fields[step];const options=choices[field];const labels=field==='salary'?c.salary:field==='propertyType'?c.types:c.budget;
  let control=options?`<div class="lead-options" role="radiogroup" aria-labelledby="lead-question">${options.map((value,i)=>`<label class="lead-option"><input type="radio" name="${field}" value="${value}" ${values[field]===value?'checked':''}><span class="option-letter" aria-hidden="true">${String.fromCharCode(65+i)}</span><span>${labels[i]}</span><span class="option-check" aria-hidden="true">✓</span></label>`).join('')}</div>`:`<input class="lead-input" id="lead-answer" name="${field}" type="${step===5?'tel':'text'}" autocomplete="${step===0?'name':step===5?'tel':'organization-title'}" ${step===5?'inputmode="tel"':''} maxlength="${step===5?24:100}" placeholder="${c.placeholders[step]}" value="${escape(values[field])}" aria-labelledby="lead-question" aria-describedby="lead-hint lead-error" ${error?'aria-invalid="true"':''} required>`;
  if(step===5)control+=`<label class="lead-whatsapp"><input type="checkbox" name="whatsapp" ${values.whatsapp?'checked':''}><span>${c.whatsapp}</span></label><p class="lead-privacy">${c.privacy}</p>`;
  root.innerHTML=`<div class="lead-topline"><span class="lead-eyebrow">${c.eyebrow}</span><span class="lead-step-count">${c.step} ${step+1} ${c.of} 6</span></div><div class="lead-progress" role="progressbar" aria-label="${c.step}" aria-valuemin="1" aria-valuemax="6" aria-valuenow="${step+1}" aria-valuetext="${c.step} ${step+1} ${c.of} 6"><span style="width:${(step+1)/6*100}%"></span></div><p class="lead-welcome">${c.title}</p><form novalidate aria-busy="${busy}"><div class="lead-slide ${direction<0?'lead-reverse':''}"><h2 id="lead-question" tabindex="-1">${c.questions[step]}</h2><p id="lead-hint" class="lead-hint">${c.hints[step]}</p><fieldset ${busy?'disabled':''}>${control}</fieldset></div><p id="lead-error" class="lead-error" role="alert">${error?c[error]:''}</p><div class="lead-actions"><button type="button" class="lead-back" ${step===0||busy?'disabled':''}>${c.back}</button><button type="submit" class="lead-primary" ${busy?'disabled':''}>${busy?c.sending:step===5?c.submit:c.next}</button></div></form>`;
  const form=root.querySelector('form');form.addEventListener('input',e=>{if(e.target.name==='whatsapp')values.whatsapp=e.target.checked;else if(e.target.name)values[e.target.name]=e.target.value;error='';root.querySelector('#lead-error').textContent='';root.querySelector('.lead-input')?.removeAttribute('aria-invalid')});
  root.querySelector('.lead-back').addEventListener('click',()=>{if(step>0&&!busy){step--;direction=-1;error='';render(true)}});
  form.addEventListener('submit',submit);if(focus)root.querySelector('#lead-question').focus({preventScroll:true});
 }
 async function submit(event){event.preventDefault();if(busy)return;error='';const value=values[fields[step]].trim();
  if(!value)error='required';else if((step===0||step===2)&&value.length<2)error='textError';else if(step===5&&!/^\+?[0-9]{9,15}$/.test(value.replace(/[\s()-]/g,'')))error='phoneError';
  if(error){root.querySelector('#lead-error').textContent=t()[error];const input=root.querySelector('.lead-input');input?.setAttribute('aria-invalid','true');(input||root.querySelector('input'))?.focus({preventScroll:true});return}
  if(step<5){step++;direction=1;render(true);return}
  busy=true;render();const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),20000);
  try{const endpoint=location.hostname==='haneeshazli.github.io'?'https://ophira-resort-dutamas.vercel.app/api/leads':'/api/leads';const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...values,id,language:language==='en'?'en':'bm'}),signal:controller.signal});if(!response.ok)throw new Error('submit');const result=await response.json();if(result.ok!==true)throw new Error('submit');complete=true;busy=false;Object.keys(values).forEach(key=>values[key]=key==='whatsapp'?false:'');render(true)}catch{busy=false;error='error';render(true)}finally{clearTimeout(timeout)}
 }
 document.addEventListener('languagechange',()=>render());render();
})();
